self.KB_CONTENT["card:778995"]={"id":"card:778995","ty":"card","sourceId":"778995","title":"『暫出/入歸還建立作業(IDL)』中的『課稅別 (TH010)』為何？","ver":"GP4以上","topic":"暫出入","keywords":["暫出入","課稅別","稅率"],"y":"other","answer":"* 分為1.內含、2.外加、3.零稅率、4.免稅及9.不計稅五種課稅別。* 此欄位僅作顯示。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
