self.KB_CONTENT["card:794993"]={"id":"card:794993","ty":"card","sourceId":"794993","title":"執行『標單匯入作業-EPMB14』匯入成功後，才發現金額填寫有問題，該如何重新匯入？","ver":"GP4","topic":"epmi","keywords":["epmi","客戶","訂單","預算"],"y":"error","answer":"修改匯入EXCEL檔案並刪除金額填寫錯誤之客戶訂單(EPMI19)與預算控管(EPMI15)，重新執行『標單匯入作業-EPMB14』即可。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
