self.KB_CONTENT["field:830918"]={"id":"field:830918","ty":"field","sourceId":"830918","title":"原幣稅額","ver":"GP4 以上","topic":"","keywords":[],"job":"應付憑單建立作業","code":"","answer":"可以查看『供應廠商資料建立作業-PURI01』的【稅額計算方式】是否為''單身單筆資料計算''，如果需要手動更改【原幣稅額】則【稅額計算方式】需選擇''單身單筆計算''，若選擇''整張資料計算''則更改【原幣稅額】後儲存確認系統會重新計算因此【原幣稅額】會跳回原本稅額數字","file":"fields.jsonl"};
self.KB_CONTENT["field:828003"]={"id":"field:828003","ty":"field","sourceId":"828003","title":"採購單","ver":"GP4 以上","topic":"","keywords":[],"job":"應付憑單建立作業","code":"","answer":"查看後，『應付憑單建立作業』來源【採購】開窗無符合資料，確認『採購單』需登打【訂金比率】，才可以開窗帶入『採購單』","file":"fields.jsonl"};
