self.KB_CONTENT["field:756560"]={"id":"field:756560","ty":"field","sourceId":"756560","title":"金額","ver":"iGP","topic":"","keywords":[],"job":"轉撥單據建立作業","code":"TB011","answer":"* 金額=數量×單位成本。* 依「共用參數-本國幣別」中之設定做成本金額取位。","file":"fields.jsonl"};
