self.KB_CONTENT["field:778627"]={"id":"field:778627","ty":"field","sourceId":"778627","title":"不同計劃批號跳頁","ver":"GP4以上","topic":"","keywords":[],"job":"LRPR02 批次採購計劃明細表","code":"","answer":"* 不同的計劃批號是否自動跳下頁。* 系統設不同計劃批號時不跳頁。","file":"fields.jsonl"};
